<script lang="ts">
import type {CareerRecord} from '../data/career';import type {Runner} from '../data/types';import type {ReferenceData} from '../data/reference';import {runnerName} from '../data/reference';
import {legacyRunner,familyFactors,parentAffinity,grandparentAffinity,g1Wins,whiteSparkCount,ancestorScenario,type Affinity} from '../data/career-display';import UmaPortrait from './UmaPortrait.svelte';import RatingBadge from './RatingBadge.svelte';import CopyTrainer from './CopyTrainer.svelte';import CareerFactors from './CareerFactors.svelte';import G1Wins from './G1Wins.svelte';
export let index:number;export let career:CareerRecord;export let trainee:Runner;export let reference:ReferenceData|null;export let runners:Runner[];
let selectedPosition:number|null=null,previous:CareerRecord;
$: if(previous!==career){previous=career;selectedPosition=null;}
$: parent=career.legacies.find(l=>l.position===index*10);$: grandparents=career.legacies.filter(l=>l.position===index*10+1||l.position===index*10+2).sort((a,b)=>a.position-b.position);

$: family=parent?[parent,...grandparents]:[];
$: selected=family.find(c=>c.position===selectedPosition)??null;
$: shown=selected??parent;
$: runner=parent?legacyRunner(parent):null;
$: affinity=parent?parentAffinity(parent,grandparents):null;
$: borrowed=!!parent?.trainerId&&parent.trainerId!==(trainee.trainerId??career.trainerId);
$: owner=parent?.trainerName??runners.find(r=>r.trainerId&&r.trainerId===parent?.trainerId)?.trainer??'';
const fmt=(n:number|null|undefined)=>n?.toLocaleString()??'—';
const affinityHelp=(a:Affinity)=>`${fmt(a.base)} parent–grandparent base + ${fmt(a.race)} shared G1 bonus`;
function select(position:number){selectedPosition=selectedPosition===position?null:position;}
</script>
<section class="legacy-family" aria-label={`Parent ${index}`}>
<header><div class="legacy-title"><small>PARENT {index}</small><h3>{runner?runnerName(reference,runner):'Not recorded'}</h3>{#if borrowed&&parent}<div class="owner"><span>Borrowed from: {owner}</span><CopyTrainer value={parent.trainerId}/></div>{/if}</div>{#if parent}<RatingBadge score={null} rank={parent.rank}/>{/if}</header>
{#if parent&&runner&&shown}<div class="legacy-content"><div class="family-tree">
<button class="parent-node portrait-filter" class:selected={selected===parent} aria-pressed={selected===parent} aria-label={`Show ${runnerName(reference,runner)} sparks`} onclick={()=>select(parent!.position)}><UmaPortrait {runner} size={88}/><strong>{runnerName(reference,runner)}</strong><span class="affinity" title={affinity?affinityHelp(affinity):undefined}>♡ {fmt(affinity?.total)}<small>family affinity</small></span></button>
<div class="tree-branch"></div><div class="grandparents">{#each grandparents as gp}{@const gr=legacyRunner(gp)}{@const gpAffinity=grandparentAffinity(parent,gp)}<button class="portrait-filter" class:selected={selected===gp} aria-pressed={selected===gp} aria-label={`Show ${runnerName(reference,gr)} sparks`} onclick={()=>select(gp.position)}><UmaPortrait runner={gr} size={61}/><strong>{runnerName(reference,gr)}</strong><span class="affinity" title={affinityHelp(gpAffinity)}>♡ {fmt(gpAffinity.total)}</span></button>{:else}<small>Grandparents not recorded.</small>{/each}</div></div>
<div class="legacy-details"><div class="legacy-facts"><span>{shown.saddles===null?'—':g1Wins(shown).size} <small>G1 wins</small></span><span>{shown.factors===null?'—':whiteSparkCount(shown)} <small>white sparks</small></span>{#if ancestorScenario(shown)}<span class="scenario">{ancestorScenario(shown)}</span>{/if}</div>
<div class="filter-heading">{#if selected}<strong>{runnerName(reference,legacyRunner(selected))} sparks</strong>{/if}{#if selected}<button onclick={()=>selectedPosition=null}>Show all</button>{:else}<small>Gold stars are the parent’s contribution</small>{/if}</div>
<CareerFactors combined={familyFactors(family,parent,selected)}/>
<G1Wins career={shown}/>
</div></div>{/if}</section>
<style>.legacy-family{border:1px solid var(--border);border-radius:10px;overflow:hidden;background:var(--panel)}header{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:17px 20px;background:var(--panel-raised);border-bottom:1px solid var(--border)}.legacy-title{min-width:0;overflow-wrap:anywhere}.legacy-title>small{font-size:var(--font-9);letter-spacing:.12em;color:var(--accent-text)}h3{font-size:var(--font-19);margin:5px 0}.owner{display:flex;align-items:center;gap:12px;flex-wrap:wrap;font-size:var(--font-12);color:var(--muted)}.legacy-content{display:grid;grid-template-columns:minmax(0,170px) minmax(0,1fr);gap:22px;padding:20px}.family-tree{text-align:center;padding-top:6px;min-width:0}.portrait-filter{white-space:normal;text-align:center;background:transparent;border:1px solid transparent;border-radius:9px;padding:7px;display:flex;flex-direction:column;align-items:center;gap:7px;width:100%;min-width:0;position:relative}.portrait-filter:hover,.portrait-filter.selected{background:var(--accent-soft);border-color:var(--accent)}.family-tree strong{display:block;max-width:100%;overflow-wrap:anywhere;font-size:var(--font-12);line-height:1.4}.affinity{display:block;color:#f288ac;font-size:var(--font-15);font-weight:650;font-variant-numeric:tabular-nums}.affinity small{display:block;font-size:var(--font-9);color:var(--muted);font-weight:400;margin-top:3px}.tree-branch{height:18px;border-left:1px solid var(--border);width:0;margin:4px auto}.grandparents{display:grid;grid-template-columns:minmax(0,1fr);gap:22px}.grandparents .portrait-filter+.portrait-filter:before{content:'';position:absolute;left:50%;top:-22px;height:20px;border-left:1px solid var(--border)}.grandparents .affinity{font-size:var(--font-12);color:#69c6ef}.legacy-details{min-width:0}.legacy-facts{display:flex;gap:20px;margin-bottom:18px;flex-wrap:wrap;font-weight:650;font-size:var(--font-16);align-items:center}.legacy-facts small{font-weight:400;font-size:var(--font-11);color:var(--muted)}.legacy-facts .scenario{font-size:var(--font-11);color:var(--muted);font-weight:400}.filter-heading{display:flex;gap:10px;align-items:center;justify-content:space-between;margin-bottom:13px}.filter-heading strong{min-width:0;overflow-wrap:anywhere;font-size:var(--font-12);font-weight:500}.filter-heading small,.filter-heading button{font-size:var(--font-10);color:var(--muted)}@media(max-width:850px){.legacy-content{grid-template-columns:minmax(0,140px) minmax(0,1fr);gap:16px;padding:15px}}</style>
